#!/bin/bash
# OpenVPN3 Client Installer
# Generated by MarcScript Build System

GREEN='\033[0;32m'
NC='\033[0m'

print_info() { echo -e "[ ${GREEN}INFO${NC} ] $1"; }

if [ "$EUID" -ne 0 ]; then
    echo "Please run as root"
    exit 1
fi

INSTALL_DIR="/usr/local/bin"
CURRENT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

print_info "Installing OpenVPN3 client..."

# Install required runtime libraries
apt update
apt install -y libasio-dev libfmt-dev liblz4-dev libjsoncpp-dev libssl-dev libxxhash-dev libcap-dev

# Copy binaries
cp $CURRENT_DIR/ovpncli $INSTALL_DIR/
cp $CURRENT_DIR/ovpnclis $INSTALL_DIR/ 2>/dev/null || true
chmod 755 $INSTALL_DIR/ovpncli

# Create symlinks
ln -sf $INSTALL_DIR/ovpncli /usr/bin/ovpncli 2>/dev/null || true
ln -sf $INSTALL_DIR/ovpncli /usr/local/bin/openvpn3 2>/dev/null || true

print_info "OpenVPN3 installed successfully!"
print_info "Usage: ovpncli [options] config.ovpn"
print_info "Example: ovpncli client.ovpn"

# Test binary
if $INSTALL_DIR/ovpncli --version 2>/dev/null || $INSTALL_DIR/ovpncli -h 2>/dev/null | head -1; then
    print_info "Binary verified successfully"
fi
